import sys,json,pathlib,html,argparse,xml.etree.ElementTree as ET
ap=argparse.ArgumentParser();ap.add_argument('root',type=pathlib.Path);ap.add_argument('runs',nargs='*',type=pathlib.Path);ap.add_argument('--tests',nargs='*',type=pathlib.Path,default=[]);args=ap.parse_args()
root=args.root.resolve();runs=[p.resolve() for p in args.runs] or ([root] if (root/'continuity.jsonl').exists() else sorted(p for p in root.iterdir() if p.is_dir() and (p/'continuity.jsonl').exists()))
validation=[]
for test in args.tests:
 node=ET.parse(test).getroot();validation.append({'path':test.resolve().relative_to(root).as_posix(),'total':node.get('total'),'passed':node.get('passed'),'failed':node.get('failed'),'result':node.get('result')})
data=[]
for p in runs:
 result=json.loads((p/'acceptance.json').read_text()) if (p/'acceptance.json').exists() else {'passed':False,'note':'Not adjudicated'}
 files=sorted((p/'frames').glob('*.png'));frames=[{'src':f.relative_to(root).as_posix(),'frame':int(f.stem)} for f in files]
 anomalies=json.loads((p/'anomalies.json').read_text()) if (p/'anomalies.json').exists() else []
 data.append({'name':p.relative_to(root).as_posix() if p!=root else p.name,'result':result,'frames':frames,'events':anomalies})
page='''<!doctype html><meta charset="utf-8"><title>Playable combat continuity review</title><style>body{background:#101820;color:#e4edf2;font:16px system-ui;margin:24px auto;max-width:1400px}button,select{padding:8px;margin:5px}img{width:100%;background:black}pre{white-space:pre-wrap;font-size:13px}input{width:90%}.bad{color:#ffae7d}table{border-collapse:collapse}td{padding:8px;border-bottom:1px solid #34434f}</style><h1>完整可玩场景：自动实战与 HUD 连续性</h1><p>真实 AI、正常雷达调度、正常武器链路；玩家仅接收脚本化操作输入。真值仅供离线裁判，不提供给雷达或 AI。画面按约 10 Hz 截图回放，逐帧 HUD 记录保存在 continuity.jsonl。60/30 表示确定性模拟步进，不是性能帧率成绩。</p><p class="bad">覆盖通过不等于连续性通过。红色失败项保留；未执行或无法判定的项目不得记为通过。</p><p>计数说明：friendly_non_green_frames 按离线真值统计友方弹的非绿色显示，包含首次身份报告到达前的未知显示；已确认身份丢失由 friendly_identity_lost 单独判失败。</p><select id="run"></select><button id="play">播放/暂停</button><button id="prev">上一帧</button><button id="next">下一帧</button><span id="label"></span><input id="slider" type="range" min="0" value="0"><img id="image"><h2>相关自动回归</h2><pre id="validation"></pre><h2>本轮实战验收结果</h2><pre id="result"></pre><h2>事件定位（包括正常的不确定度修正）</h2><select id="event"></select><pre id="details"></pre><script>const validation=VALIDATION;document.getElementById('validation').textContent=JSON.stringify(validation,null,2);const runs=DATA;let ri=0,fi=0,playing=false;const $=id=>document.getElementById(id);runs.forEach((r,i)=>$('run').add(new Option(r.name,i)));function draw(){const r=runs[ri],f=r.frames[fi];if(!f)return;$('image').src=f.src;$('label').textContent=`截图 ${fi+1}/${r.frames.length} · 游戏帧 ${f.frame}`;$('slider').value=fi;}function load(){const r=runs[ri];fi=0;$('slider').max=Math.max(0,r.frames.length-1);$('result').textContent=JSON.stringify(r.result,null,2);$('result').className=r.result.passed?'':'bad';$('event').innerHTML='';r.events.forEach((e,i)=>$('event').add(new Option(`${e.time?.toFixed(2)}s ${e.kind} ${e.stream||''}`,i)));draw();}$('run').onchange=()=>{ri=+$('run').value;load()};$('slider').oninput=()=>{fi=+$('slider').value;draw()};$('play').onclick=()=>playing=!playing;$('prev').onclick=()=>{fi=Math.max(0,fi-1);draw()};$('next').onclick=()=>{fi=Math.min(runs[ri].frames.length-1,fi+1);draw()};$('event').onchange=()=>{const r=runs[ri],e=r.events[+$('event').value];$('details').textContent=JSON.stringify(e,null,2);let best=0;for(let i=0;i<r.frames.length;i++)if(Math.abs(r.frames[i].frame-e.frame)<Math.abs(r.frames[best].frame-e.frame))best=i;fi=best;draw()};setInterval(()=>{if(playing){fi=(fi+1)%runs[ri].frames.length;draw()}},100);load();</script>'''
(root/'review.html').write_text(page.replace('VALIDATION',json.dumps(validation,ensure_ascii=False)).replace('DATA',json.dumps(data).replace('</','<\\/')),encoding='utf-8')
print(root/'review.html')
